S=/tmp/claude-1000/-home-bench-auto-arch-tournament/c4aa8f8e-836f-4266-9ad0-a31f867c07f9/scratchpad; echo "== memwatch start $(date -u +%H:%M:%S) (with top process)" >> $S/memwatch.log; end=$(( $(date +%s) + 3300 )); min=999999; while [ $(date +%s) -lt $end ]; do a=$(free -m | awk '/Mem:/{print $7}'); s=$(free -m | awk '/Swap:/{print $3}'); top=$(ps -eo user:12=,pid=,rss=,comm= --sort=-rss | head -1 | awk '{printf "%s/%s/%s/%.1fG", $1, $2, $4, $3/1048576}'); [ "$a" -lt "$min" ] && min=$a; echo "$(date -u +%H:%M:%S) avail=${a}MB swap=${s}MB top=$top" >> $S/memwatch.log; if [ "$a" -lt 3000 ]; then echo "LOW MEMORY $(date -u +%H:%M:%S) avail=${a}MB swap=${s}MB top=$top"; ps -eo user:12,pid,ppid,rss,etimes,args --sort=-rss | head -3 | cut -c1-250; exit 0; fi; sleep 5; done; echo "memwatch window ended $(date -u +%H:%M:%S), min avail ${min}MB"